export class Reasoner extends Effect.Service<Reasoner>()("Reasoner", {
  effect: Effect.gen(function*() {
    return {
      // Materialize RDFS inferences
      reason: (graph: RdfStore, rules: ReasoningRules) => 
        Effect.gen(function*() {
