export class ViolationExplainer extends Effect.Service<ViolationExplainer>()(...) {
  explain: (violation: ShaclViolation, context: ExplanationContext) =>
    Effect.gen(function*() {
      // Build context: violated shape + focus node + nearby triples
      const prompt = buildExplanationPrompt(violation, context)

      // Generate explanation via LLM
      const explanation = yield* llm.generate(prompt)

      // Generate fix suggestion
      const suggestion = yield* llm.generate(buildFixPrompt(violation))

      return { explanation, suggestion, severity: violation.severity }
    })
}
```

